package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the telephone on a create request to E.164 form (see {@link TelephoneNormalizer}).
 * Stores the E.164 value back on the request (mutating the shared {@code @Val} object) so
 * {@link BuildOwner} and the response carry it; rejects with {@link InvalidTelephoneException}
 * (400) when the number cannot form valid E.164. Runs after {@link ValidateNewOwner} has
 * confirmed the field is present.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String raw = request.getTelephone();
        String e164 = TelephoneNormalizer.toE164(raw);
        if (e164 == null) {
            throw new InvalidTelephoneException(raw);
        }
        request.setTelephone(e164);
    }
}
===== TelephoneNormalizer =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Shared telephone normalization to E.164 form. Strips spaces, dashes and brackets, then:
 * keeps a leading '+' and country code when present; otherwise assumes country code '+61'
 * and drops a single leading '0' from the national digits. The result must carry 8 to 15
 * digits after the '+'. Used both to canonicalize an incoming request's telephone and to
 * compare it against the telephones already stored on other owners.
 */
final class TelephoneNormalizer {

    private TelephoneNormalizer() {
    }

    /**
     * Returns the E.164 representation of {@code raw} (a leading '+' followed by 8-15
     * digits), or {@code null} when it cannot form a valid E.164 number.
     */
    static String toE164(String raw) {
        if (raw == null) {
            return null;
        }
        String cleaned = raw.replaceAll("[\\s()\\-]", "");
        String digits;
        if (cleaned.startsWith("+")) {
            digits = cleaned.substring(1);
        } else {
            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
            digits = "61" + national;
        }
        if (!digits.matches("[0-9]{8,15}")) {
            return null;
        }
        return "+" + digits;
    }
}
===== NormalizeOwnerEmail =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;
import java.util.regex.Pattern;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidEmailException;

/**
 * Normalizes an optional email on an owner request. Email is not required: a null or blank
 * value is left untouched. When present it must be a syntactically valid address, otherwise
 * the request is rejected with {@link InvalidEmailException} (400). A valid address is stored
 * back on the shared {@code @Val} request lower-cased, so {@link BuildOwner}/{@link ApplyOwner}
 * and the response carry the canonical form.
 */
public class NormalizeOwnerEmail {

    /** Local part and domain each a run of non-space, non-'@' characters, domain dotted. */
    private static final Pattern EMAIL = Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$");

    public void service(@Val OwnerFieldsDto request) throws InvalidEmailException {
        String raw = request.getEmail();
        if (raw == null || raw.isBlank()) {
            return;
        }
        String trimmed = raw.trim();
        if (!EMAIL.matcher(trimmed).matches()) {
            throw new InvalidEmailException(raw);
        }
        request.setEmail(trimmed.toLowerCase(Locale.ROOT));
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Rejects a create request whose last name and address already belong to an existing owner,
 * so the pair maps to a 409 — unless the request opts in with {@code sharesHousehold=true},
 * declaring that the two owners share a household. Comparison is by {@link HouseholdKey}, so
 * case and whitespace differences do not hide a collision.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String key = HouseholdKey.of(request.getLastName(), request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (key.equals(HouseholdKey.of(existing.getLastName(), existing.getAddress()))) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== HouseholdKey =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

/**
 * Canonical key identifying a household by its owner's last name and address. Two owners
 * belong to the same household when their keys are equal: last name and address are compared
 * case-insensitively with leading/trailing and repeated whitespace collapsed to a single
 * space, so incidental formatting differences do not hide a match.
 */
final class HouseholdKey {

    private HouseholdKey() {
    }

    static String of(String lastName, String address) {
        return normalize(lastName) + '�' + normalize(address);
    }

    /**
     * Stable identifier shared by every owner of a household: the SHA-256 hex digest of the
     * canonical {@link #of(String, String) key}. Purely derived from last name and address, so
     * two owners in the same household always get the same value regardless of creation order.
     */
    static String id(String lastName, String address) {
        byte[] digest;
        try {
            digest = MessageDigest.getInstance("SHA-256")
                    .digest(of(lastName, address).getBytes(StandardCharsets.UTF_8));
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 is required but unavailable", ex);
        }
        StringBuilder hex = new StringBuilder(digest.length * 2);
        for (byte b : digest) {
            hex.append(Character.forDigit((b >> 4) & 0xF, 16));
            hex.append(Character.forDigit(b & 0xF, 16));
        }
        return hex.toString();
    }

    private static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }
}
